xpath.script:
(function () {
    const canvas = document.getElementById('signPadCanvas');
    const input = document.getElementById('signatureDataInput');
    const clearBtn = document.getElementById('clearSignPad');
    if (!canvas || !input) return;
    const ctx = canvas.getContext('2d');
    ctx.lineWidth = 2.2;
    ctx.lineCap = 'round';
    ctx.strokeStyle = '#111827';
    let drawing = false;
    const pos = (e) => {
        const rect = canvas.getBoundingClientRect();
        const pt = e.touches ? e.touches[0] : e;
        return {
            x: (pt.clientX - rect.left) * (canvas.width / rect.width),
            y: (pt.clientY - rect.top) * (canvas.height / rect.height)
        };
    };
    const start = (e) => { drawing = true; const p = pos(e); ctx.beginPath(); ctx.moveTo(p.x, p.y); };
    const move = (e) => { if (!drawing) return; e.preventDefault(); const p = pos(e); ctx.lineTo(p.x, p.y); ctx.stroke(); input.value = canvas.toDataURL('image/png'); };
    const stop = () => { if (drawing) { drawing = false; input.value = canvas.toDataURL('image/png'); } };
    canvas.addEventListener('mousedown', start);
    canvas.addEventListener('mousemove', move);
    window.addEventListener('mouseup', stop);
    canvas.addEventListener('touchstart', start, {passive: false});
    canvas.addEventListener('touchmove', move, {passive: false});
    canvas.addEventListener('touchend', stop);
    if (clearBtn) {
        clearBtn.addEventListener('click', () => {
            ctx.clearRect(0, 0, canvas.width, canvas.height);
            input.value = '';
        });
    }
})();
